// === Tab: mySketch ===
const url = [
	"https://coolors.co/caced1-b55d00-c48613-e8ca25-676d65",
	"https://coolors.co/FFF000-1fFa8c-ffbFc4-aa93c4-602f6b",
	"https://coolors.co/38263f-593d66-cea7d6-e4d0e8-e63f39",
	"https://coolors.co/app/094074-1d7874-f18f01-ff0800-33658a"
];
let COLS;
let sh;
let obj;


function setup() {
	frameRate(0.75);
	createCanvas(1112, 834, WEBGL);
	let dep = max(width,height);
	ortho(-width / 2, width / 2, height / 2, -height / 2, -dep*2 , dep*2);

	sh = createShader(vert,frag);
	this.shader(sh);
	sh.setUniform("u_resolution", [width,height]);
	sh.setUniform("u_lightDir", [1,-1,-1]);

	init();
}


function draw() {
	init();
	//scale(1, -1);   // uncomment this line before saving an image or thumbnail	
	background(245);
	rotateX(PI/10);
	rotateY(PI/3.5);
	for(let item of obj)
	{
		item.update();
		item.display();
	}
}

function createCols(_url)
{
  let slash_index = _url.lastIndexOf('/');
  let pallate_str = _url.slice(slash_index + 1);
  let arr = pallate_str.split('-');
  for (let i = 0; i < arr.length; i++) {
    arr[i] = '#' + arr[i];
  }
  return arr;
}


function init()
{
	COLS = createCols(url[Math.floor(random(url.length))]);
	obj = [];
	let s = max(width, height)*0.7;
	let span = s/4;
	for(let x = -s/2; x <= s/2; x += span)
	{
		for(let z = -s/2; z <= s/2; z += span)
		{
			const ri = Math.floor(random(COLS.length));
			const ri2 = Math.floor(ri + random(1,COLS.length)) % COLS.length;
			const w = span*random(0.4,0.6);
			const h = span*random(0.5,1.5);
			const y = h/2 - height*0.1;
			obj.push(new Cube(createVector(x,y,z),createVector(w,h,w),COLS[ri],COLS[ri2]));
		}
	}
}

////////////

class Cube
{
	constructor(_pos,_size,_col1, _col2)
	{
		this.pos = _pos;
		this.size = _size;
		this.rotateOffsetX = random(TWO_PI);
		this.rotateOffsetZ = random(TWO_PI);
		this.tex = createGraphics(_size.x*2,_size.y*2);
		this.col = [_col1,_col2];
		this.spanMult = random(1,3);
		this.topPos = createVector(_size.x * random(-0.4,0.4),0,_size.z * random(-0.4,0.4));
		this.rectWIndow = random() > 0.3 ? true: false;
	}

	update()
	{
		this.tex.noStroke();
		let margine = this.tex.width*0.1;
		var span = (this.tex.width-margine*2)/9;
		this.tex.background(this.col[0]);
		let i = 0;
		this.tex.fill(this.col[1]);
		for(let y = this.tex.height-margine*1.5; y >= margine; y -= span*this.spanMult)
		{
			for(let x = margine; x <= this.tex.width-margine; x += span)
			{
				if(i %2 == 0){
					if(this.rectWIndow)this.tex.rect(x,y,span,span);
					else this.tex.ellipse(x,y,span,span);
				}
				i++;
			}
		}
	}

	display()
	{
		noStroke();
		sh.setUniform("u_tex",this.tex);
		push();
		translate(this.pos);
		box(this.size.x,this.size.y,this.size.z);
		this.tex.background(this.col[1]);
		translate(0,this.size.y*0.525,0);
		box(this.size.x,this.size.y*0.05,this.size.z);
		this.tex.background(this.col[0]);
		translate(this.topPos);
		box(this.size.x*0.1,this.size.y*0.15,this.size.z*0.1);
		pop();
	}
}

